static void launcher_periodic_cb(lv_timer_t *timer)
{
  char buf[32];
  struct mallinfo mi;

  UNUSED(timer);

  launcher_format_uptime(buf, sizeof(buf));

  if (g_lock_scr != NULL && lv_screen_active() == g_lock_scr)
    {
      lv_label_set_text(g_lock_clock, buf);
    }
  else if (g_home_scr != NULL && lv_screen_active() == g_home_scr)
    {
      mi = mallinfo();
      lv_label_set_text(g_home_clock, buf);
      lv_label_set_text_fmt(g_home_uptime, "up %us · heap %uKB free",
                            (unsigned)buf[0], mi.fordblks / 1024);
    }

  g_fps = g_refr_count;
  g_refr_count = 0;

  if (g_about_scr != NULL)
    {
      lv_label_set_text_fmt(g_about_fps, "fps: %u", g_fps);
    }

  if (g_home_scr != NULL)
    {
      lv_label_set_text_fmt(g_home_fps, "%u fps", g_fps);
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  lv_nuttx_dsc_t info;
  lv_nuttx_result_t result;
  char buf[32];

  UNUSED(argc);
  UNUSED(argv);

  lv_init();

  lv_nuttx_dsc_init(&info);
  lv_nuttx_init(&info, &result);

  if (result.disp == NULL)
    {
      fprintf(stderr, "launcher: no display found\n");
      return 1;
    }

  lv_display_add_event_cb(result.disp, launcher_refr_event_cb,
                          LV_EVENT_REFR_START, NULL);

  launcher_create_lock_scr();
  launcher_create_home_scr();
  launcher_create_about_scr();
  launcher_create_paint_scr();

  /* Wire home buttons to their target screens */

  {
    lv_obj_t *btn;

    btn = lv_obj_get_child_by_id(g_home_scr, 0); /* placeholder, reset below */
    UNUSED(btn);
  }

  launcher_home_btn_rebind();

  lv_screen_load(g_lock_scr);

  launcher_format_uptime(buf, sizeof(buf));
  lv_label_set_text(g_lock_clock, buf);

  lv_timer_create(launcher_periodic_cb, 1000, NULL);

  while (1)
    {
      uint32_t idle = lv_timer_handler();
      idle = idle ? idle : 1;
      usleep(idle * 1000);
    }

  return 0;
}

